let _mothraMemoryData = null;
let _supabaseClient = null;
let _supabaseRealtimeChannel = null;

// Ambil konfigurasi aktif (mendukung override dari panel admin via localStorage)
function getSupabaseConfig() {
  let customUrl = '';
  let customKey = '';
  try {
    if (typeof localStorage !== 'undefined') {
      customUrl = localStorage.getItem('mothra_supabase_url') || '';
      customKey = localStorage.getItem('mothra_supabase_key') || '';
    }
  } catch (e) {}

  const url = (customUrl && customUrl.trim()) || SUPABASE_CONFIG.url;
  const anonKey = (customKey && customKey.trim()) || SUPABASE_CONFIG.anonKey;
  const isConfigured = Boolean(
    url &&
    anonKey &&
    !url.includes('YOUR_SUPABASE_PROJECT_ID') &&
    !anonKey.includes('YOUR_SUPABASE_ANON') &&
    url.startsWith('https://')
  );

  return {
    url,
    anonKey,
    tableName: SUPABASE_CONFIG.tableName || 'mothra_cms',
    docId: SUPABASE_CONFIG.docId || 'main',
    isConfigured
  };
}

// Inisialisasi Supabase Client & Realtime Subscription
function initSupabase() {
  const config = getSupabaseConfig();
  if (!config.isConfigured) {
    console.log('ℹ️ [MOTHRA CMS] Supabase belum dikonfigurasi aktif. Menggunakan LocalStorage cache.');
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('mothra_supabase_status', {
        detail: { status: 'STANDBY', connected: false, message: 'Belum terhubung ke Supabase' }
      }));
    }
    return null;
  }

  if (typeof window !== 'undefined' && window.supabase && typeof window.supabase.createClient === 'function') {
    try {
      _supabaseClient = window.supabase.createClient(config.url, config.anonKey);
      window.supabaseClient = _supabaseClient;
      console.log('✅ [MOTHRA CMS] Supabase Client terhubung ke:', config.url);
      subscribeSupabaseRealtime();
      fetchMothraDataOnline();
      return _supabaseClient;
    } catch (err) {
      console.error('❌ [MOTHRA CMS] Gagal inisialisasi Supabase Client:', err);
    }
  }
  return null;
}

// Berlangganan Event Realtime WebSocket Supabase
function subscribeSupabaseRealtime() {
  if (!_supabaseClient) return;
  const config = getSupabaseConfig();
  try {
    if (_supabaseRealtimeChannel) {
      try {
        _supabaseClient.removeChannel(_supabaseRealtimeChannel);
      } catch (e) {}
    }
    _supabaseRealtimeChannel = _supabaseClient
      .channel('mothra_cms_realtime_channel')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: config.tableName, filter: `id=eq.${config.docId}` },
        (payload) => {
          console.log('⚡ [MOTHRA REALTIME] Update database online diterima:', payload);
          if (payload.new && payload.new.data) {
            applyIncomingOnlineData(payload.new.data);
          }
        }
      )
      .subscribe((status) => {
        console.log('⚡ [MOTHRA REALTIME] Status koneksi:', status);
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('mothra_supabase_status', {
            detail: { status: status, connected: status === 'SUBSCRIBED' }
          }));
        }
      });
  } catch (e) {
    console.warn('Realtime subscription error:', e);
  }
}

// Tarik data online dari Supabase (SDK + Direct REST API dengan Anti-Cache)
async function fetchMothraDataOnline() {
  const config = getSupabaseConfig();
  if (!config.isConfigured) return getMothraData();

  // 1. Coba via Supabase JS SDK jika tersedia
  if (_supabaseClient) {
    try {
      const { data, error } = await _supabaseClient
        .from(config.tableName)
        .select('*')
        .eq('id', config.docId)
        .single();

      if (!error && data && data.data) {
        console.log('📥 [MOTHRA CMS] Berhasil mengambil data online via Supabase SDK!');
        return applyIncomingOnlineData(data.data);
      }
    } catch (e) {
      console.warn('SDK fetch error, falling back to REST:', e);
    }
  }

  // 2. Fallback Direct HTTPS REST API (Anti-Cache untuk Mobile/HP)
  try {
    const res = await fetch(`${config.url}/rest/v1/${config.tableName}?id=eq.${config.docId}&select=*&_t=${Date.now()}`, {
      headers: {
        'apikey': config.anonKey,
        'Authorization': 'Bearer ' + config.anonKey,
        'Cache-Control': 'no-cache, no-store, must-revalidate',
        'Pragma': 'no-cache'
      }
    });

    if (res.ok) {
      const rows = await res.json();
      if (Array.isArray(rows) && rows.length > 0 && rows[0].data) {
        console.log('📥 [MOTHRA CMS] Berhasil mengambil data online via Direct REST API!');
        return applyIncomingOnlineData(rows[0].data);
      }
    }
  } catch (err) {
    console.warn('⚠️ [MOTHRA CMS] Error fetch online data:', err);
  }

  return getMothraData();
}

// Terapkan data yang datang dari Supabase ke memory & UI
function applyIncomingOnlineData(data) {
  if (!data) return getMothraData();
  sanitizeMothraData(data);
  _mothraMemoryData = data;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (e) {}
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('mothra_data_updated', { detail: data }));
  }
  return data;
}

// ============================================================
// CYBER SECURITY PROTECTION: ANTI-SQL INJECTION & ANTI-XSS SUITE
// ============================================================

/**
 * Membersihkan input teks dari serangan SQL Injection, Stored XSS, dan payload berbahaya
 * @param {string} val Input string
 * @param {boolean} allowBase64 Apakah memperbolehkan data URL base64 gambar
 * @returns {string} String yang sudah disanitasi dan aman
 */
function sanitizeSecurityInput(val, allowBase64 = true) {
  if (val === null || val === undefined) return '';
  if (typeof val !== 'string') return val;

  let str = val;

  // Jika merupakan base64 image yang valid, verifikasi prefix aman
  if (allowBase64 && str.startsWith('data:image/')) {
    // Pastikan hanya format image MIME yang diizinkan (png, jpeg, webp, gif, svg+xml)
    if (/^data:image\/(png|jpeg|jpg|webp|gif|svg\+xml);base64,[A-Za-z0-9+/=]+$/.test(str.substring(0, 100))) {
      return str;
    }
  }

  // 1. Netralkan pola SQL Injection berbahaya
  const sqlPatterns = [
    /(\b(UNION(\s+ALL)?|SELECT|INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|EXEC|EXECUTE)\b\s+)/gi,
    /(--|#|\/\*|\*\/)/g, // SQL comments
    /(;\s*(DROP|DELETE|UPDATE|INSERT|SELECT|ALTER|CREATE))/gi, // Chained SQL queries
    /(\bOR\b\s+['"\d\w]+\s*=\s*['"\d\w]+)/gi, // Tautology like OR 1=1
    /(\bAND\b\s+['"\d\w]+\s*=\s*['"\d\w]+)/gi,
    /(\b(pg_sleep|sleep|benchmark|waitfor\s+delay|load_file|into\s+outfile|information_schema|pg_catalog)\b)/gi
  ];

  sqlPatterns.forEach(pattern => {
    str = str.replace(pattern, '');
  });

  // 2. Netralkan pola XSS (Cross Site Scripting) berbahaya
  const xssPatterns = [
    /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
    /<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi,
    /<object\b[^<]*(?:(?!<\/object>)<[^<]*)*<\/object>/gi,
    /<embed\b[^<]*(?:(?!<\/embed>)<[^<]*)*<\/embed>/gi,
    /javascript\s*:/gi,
    /data\s*:\s*text\/html/gi,
    /\bon\w+\s*=\s*["'][^"']*["']/gi, // Event handlers like onload="...", onerror="..."
    /\bon\w+\s*=\s*[^>\s]+/gi // Event handlers without quotes
  ];

  xssPatterns.forEach(pattern => {
    str = str.replace(pattern, '');
  });

  // 3. Batasi panjang string wajar untuk mencegah buffer/payload flood (kecuali image)
  if (str.length > 5000 && !str.startsWith('data:image/')) {
    str = str.substring(0, 5000);
  }

  return str.trim();
}

/**
 * Sanitasi rekursif untuk seluruh pohon objek / array data sebelum disimpan ke database
 */
function sanitizeDataDeep(obj) {
  if (!obj || typeof obj !== 'object') return obj;

  if (Array.isArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      if (typeof obj[i] === 'string') {
        obj[i] = sanitizeSecurityInput(obj[i]);
      } else if (typeof obj[i] === 'object') {
        sanitizeDataDeep(obj[i]);
      }
    }
  } else {
    for (const key of Object.keys(obj)) {
      if (typeof obj[key] === 'string') {
        obj[key] = sanitizeSecurityInput(obj[key]);
      } else if (typeof obj[key] === 'object') {
        sanitizeDataDeep(obj[key]);
      }
    }
  }
  return obj;
}

// Auto-heal dan sanitasi struktur data
function sanitizeMothraData(data) {
  if (!data) return;
  if (!data.partnerships || !Array.isArray(data.partnerships) || data.partnerships.length === 0) {
    data.partnerships = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.partnerships));
  }
  if (!data.categories || !Array.isArray(data.categories) || data.categories.length === 0) {
    data.categories = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.categories));
  }
  if (!data.roles || !Array.isArray(data.roles) || data.roles.length === 0) {
    data.roles = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.roles));
  }
  if (!data.lineup || !Array.isArray(data.lineup) || data.lineup.length === 0) {
    data.lineup = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.lineup));
  }
  if (!data.schedule) {
    data.schedule = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.schedule));
  }
  if (!data.records || !Array.isArray(data.records)) {
    data.records = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.records));
  }
  if (!data.gallery || !Array.isArray(data.gallery)) {
    data.gallery = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.gallery));
  }
  if (!data.hero) {
    data.hero = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.hero));
  }
  if (!data.dossier) {
    data.dossier = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.dossier));
  }
  if (data.dossier) {
    if (!data.dossier.divisionLabel) data.dossier.divisionLabel = DEFAULT_MOTHRA_DATA.dossier.divisionLabel;
    if (!data.dossier.city) data.dossier.city = DEFAULT_MOTHRA_DATA.dossier.city;
    if (!data.dossier.unit) data.dossier.unit = DEFAULT_MOTHRA_DATA.dossier.unit;
    if (!data.dossier.status) data.dossier.status = DEFAULT_MOTHRA_DATA.dossier.status;
    if (!data.dossier.values || !Array.isArray(data.dossier.values) || data.dossier.values.length === 0) {
      data.dossier.values = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.dossier.values));
    }
  }
  if (!data.ads) {
    data.ads = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.ads));
  }
  if (data.ads) {
    if (!data.ads.topBanner) data.ads.topBanner = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.ads.topBanner));
    if (!data.ads.sponsorTicker) data.ads.sponsorTicker = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.ads.sponsorTicker));
    if (data.ads.sponsorTicker) {
      if (data.ads.sponsorTicker.logoWidth === undefined) data.ads.sponsorTicker.logoWidth = 36;
      if (data.ads.sponsorTicker.logoHeight === undefined) data.ads.sponsorTicker.logoHeight = 36;
      if (data.ads.sponsorTicker.cardMinWidth === undefined) data.ads.sponsorTicker.cardMinWidth = 140;
      if (data.ads.sponsorTicker.itemPaddingX === undefined) data.ads.sponsorTicker.itemPaddingX = 14;
      if (data.ads.sponsorTicker.itemPaddingY === undefined) data.ads.sponsorTicker.itemPaddingY = 8;
      if (data.ads.sponsorTicker.fontSize === undefined) data.ads.sponsorTicker.fontSize = 14;
      if (data.ads.sponsorTicker.speed === undefined) data.ads.sponsorTicker.speed = 24;
    }
    if (!data.ads.promoBanner) data.ads.promoBanner = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.ads.promoBanner));
  }
  if (!data.branding) {
    data.branding = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.branding));
  }
  if (!data.users || !Array.isArray(data.users) || data.users.length === 0) {
    data.users = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.users));
  }
  if (!data.videos || !Array.isArray(data.videos) || data.videos.length === 0) {
    data.videos = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA.videos));
  }

  // Terapkan deep security sanitization
  sanitizeDataDeep(data);
}

// Fungsi utama sinkron: Mengambil data saat ini dari memory/localStorage/default
function getMothraData() {
  if (_mothraMemoryData) {
    return _mothraMemoryData;
  }
  try {
    const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(STORAGE_KEY) : null;
    if (!raw) {
      _mothraMemoryData = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA));
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(_mothraMemoryData));
      }
      return _mothraMemoryData;
    }
    const data = JSON.parse(raw);
    sanitizeMothraData(data);
    _mothraMemoryData = data;
    return _mothraMemoryData;
  } catch (e) {
    console.warn('Storage access error, using default', e);
    _mothraMemoryData = JSON.parse(JSON.stringify(DEFAULT_MOTHRA_DATA));
    return _mothraMemoryData;
  }
}

// Fungsi simpan data: Menyimpan ke memory, LocalStorage, Supabase Online (Dual Sync), dan server lokal
function saveMothraData(data) {
  try {
    // Sanitasi data menyeluruh sebelum disimpan
    sanitizeDataDeep(data);

    data.dataVersion = Date.now();
    data.updatedAt = new Date().toISOString();
    _mothraMemoryData = data;

    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    }

    // Trigger local UI update immediately
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('mothra_data_updated', { detail: data }));

      const config = getSupabaseConfig();
      if (config.isConfigured) {
        if (!_supabaseClient) initSupabase();

        // 1. Simpan via Supabase JS SDK
        if (_supabaseClient) {
          _supabaseClient
            .from(config.tableName)
            .upsert({
              id: config.docId,
              data: data,
              data_version: data.dataVersion,
              updated_at: data.updatedAt
            })
            .then(({ error }) => {
              if (error) {
                console.error('❌ [SUPABASE SAVE ERROR]', error.message);
              } else {
                console.log('☁️ [SUPABASE SAVED] Perubahan tersimpan di database online via SDK!');
              }
            })
            .catch((err) => console.error('❌ [SUPABASE NETWORK ERROR]', err));

          // Sync to clan_videos relational table if available
          if (Array.isArray(data.videos) && data.videos.length > 0) {
            _supabaseClient
              .from('clan_videos')
              .upsert(data.videos.map(v => ({
                id: v.id,
                title: v.title,
                slug: v.slug || '',
                description: v.description || '',
                category: v.category || 'gameplay',
                video_url: v.video_url || '',
                video_id: v.video_id || '',
                thumbnail_url: v.thumbnail_url || '',
                published: v.published !== false,
                featured: !!v.featured,
                sort_order: Number(v.sort_order || 1),
                updated_at: new Date().toISOString()
              })))
              .then(({ error }) => {
                if (error) console.warn('clan_videos relational sync notice:', error.message);
              })
              .catch(() => {});
          }
        }

        // 2. Dual Sync via Direct HTTPS REST API (Jaminan 100% terkirim)
        if (typeof fetch !== 'undefined') {
          const directPayload = [{
            id: config.docId,
            data: data,
            data_version: data.dataVersion,
            updated_at: data.updatedAt
          }];
          fetch(`${config.url}/rest/v1/${config.tableName}?on_conflict=id`, {
            method: 'POST',
            headers: {
              'apikey': config.anonKey,
              'Authorization': 'Bearer ' + config.anonKey,
              'Content-Type': 'application/json',
              'Prefer': 'resolution=merge-duplicates,return=minimal'
            },
            body: JSON.stringify(directPayload)
          }).then((res) => {
            if (res.ok) console.log('☁️ [SUPABASE REST] Data tersimpan di Supabase via REST API!');
          }).catch(() => {});
        }
      }

      // 3. Simpan ke Server lokal disk via server.js jika sedang dijalankan
      try {
        fetch('/api/data', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(data)
        }).then((res) => {
          if (res.ok) console.log('Successfully synced data to disk via server.js');
        }).catch(() => {});
      } catch (err) {}
    }
    return true;
  } catch (e) {
    console.error('Failed to save data', e);
    return false;
  }
}

// Global Exports & Window Binding
if (typeof window !== 'undefined') {
  window.getMothraData = getMothraData;
  window.saveMothraData = saveMothraData;
  window.fetchMothraDataOnline = fetchMothraDataOnline;
  window.sanitizeSecurityInput = sanitizeSecurityInput;
  window.sanitizeDataDeep = sanitizeDataDeep;
  window.initSupabase = initSupabase;
  window.getSupabaseConfig = getSupabaseConfig;
  window.saveSupabaseConfig = function(url, key) {
    try {
      localStorage.setItem('mothra_supabase_url', (url || '').trim());
      localStorage.setItem('mothra_supabase_key', (key || '').trim());
    } catch (e) {}
    initSupabase();
    return fetchMothraDataOnline();
  };

  // Auto-init Supabase when DOM is ready or script loads
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => initSupabase());
  } else {
    setTimeout(() => initSupabase(), 50);
  }
}

